import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    x1, y1 = int(data[0]), int(data[1])
    x2, y2 = int(data[2]), int(data[3])

    dx = abs(x2 - x1)
    dy = abs(y2 - y1)

    if dx == 0:
        print(8 + 2 * dy)
    elif dy == 0:
        print(8 + 2 * dx)
    else:
        print(2 * (dx + dy + 2))

if __name__ == "__main__":
    solve()
